const fs = require('fs');

function extractFlight(file) {
  const h = fs.readFileSync(file, 'utf8');
  let out = '';
  const marker = 'self.__next_f.push([1,';
  let i = 0;
  while ((i = h.indexOf(marker, i)) !== -1) {
    let j = i + marker.length;
    if (h[j] !== '"') { i = j; continue; }
    // scan the JSON string literal
    let k = j + 1;
    while (k < h.length) {
      if (h[k] === '\\') { k += 2; continue; }
      if (h[k] === '"') break;
      k++;
    }
    const lit = h.slice(j, k + 1);
    try { out += JSON.parse(lit); } catch (e) { /* skip malformed chunk */ }
    i = k + 1;
  }
  return out;
}

function htmlToText(body) {
  body = body.replace(/<script[\s\S]*?<\/script>/g, '').replace(/<style[\s\S]*?<\/style>/g, '');
  body = body.replace(/<h([1-6])[^>]*>/g, (m, n) => '\n\n' + '#'.repeat(+n) + ' ');
  body = body.replace(/<\/h[1-6]>/g, '\n');
  body = body.replace(/<li[^>]*>/g, '\n- ').replace(/<\/li>/g, '');
  body = body.replace(/<\/p>/g, '\n\n').replace(/<p[^>]*>/g, '');
  body = body.replace(/<br\s*\/?>/g, '\n');
  body = body.replace(/<\/tr>/g, '\n').replace(/<\/t[dh]>/g, ' | ');
  body = body.replace(/<[^>]+>/g, '');
  body = body.replace(/&#x27;|&#39;/g, "'").replace(/&quot;/g, '"').replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
    .replace(/&mdash;/g, '—').replace(/&rsquo;/g, '’')
    .replace(/&ldquo;/g, '“').replace(/&rdquo;/g, '”');
  return body.replace(/\n{3,}/g, '\n\n').trim();
}

const file = process.argv[2];
const flight = extractFlight(file);
fs.writeFileSync(file + '.flight.txt', flight);
console.log('flight chars:', flight.length);

// Portable-text style: pull out "text":"..." runs and heading/style markers
const texts = [];
const re = /"(?:text|value|title|_key)"\s*:\s*"((?:[^"\\]|\\.)*)"/g;
let m;
while ((m = re.exec(flight))) {
  try {
    const s = JSON.parse('"' + m[1] + '"');
    if (s.length > 1) texts.push(s);
  } catch (e) { /* skip unparsable literal */ }
}
fs.writeFileSync(file + '.texts.txt', texts.join('\n'));
console.log('text runs:', texts.length);

const fs = require('fs');
const flight = fs.readFileSync(process.argv[2], 'utf8');

// Walk the payload extracting double-quoted JS string literals in source order,
// tagging the ones that immediately follow a heading marker.
const out = [];
let i = 0;
while (i < flight.length) {
  const c = flight[i];
  if (c === '"') {
    let k = i + 1;
    while (k < flight.length) {
      if (flight[k] === '\\') { k += 2; continue; }
      if (flight[k] === '"') break;
      k++;
    }
    const raw = flight.slice(i, k + 1);
    let s;
    try { s = JSON.parse(raw); } catch (e) { s = null; }
    if (s !== null) {
      const before = flight.slice(Math.max(0, i - 60), i);
      out.push({ pos: i, s, before });
    }
    i = k + 1;
    continue;
  }
  i++;
}

// Filter to prose-ish strings
const skip = /^(https?:|\/|static\/|dpl_|#|[a-f0-9]{16,}$)/;
const lines = [];
for (const { s, before } of out) {
  if (skip.test(s)) continue;
  if (s.length < 3) continue;
  // heading detection
  const isHeading = /r\.h([1-6]),\{id:$/.test(before) || /children:$/.test(before) && /r\.h[1-6]/.test(before);
  const headingMatch = before.match(/r\.h([1-6]),\{id:$/);
  if (headingMatch) { lines.push('\n\n[H' + headingMatch[1] + ' id] ' + s); continue; }
  const headingChild = before.match(/r\.h([1-6]),\{id:"[^"]*",children:$/);
  if (headingChild) { lines.push('\n\n#### ' + s); continue; }
  // prose: contains a space and a letter
  if (/[a-zA-Z]/.test(s) && (s.includes(' ') || /^[A-Za-z0-9.,;:'’“”()%-]+$/.test(s))) {
    lines.push(s);
  }
}
fs.writeFileSync(process.argv[3], lines.join('\n'));
console.log('lines:', lines.length);

